export interface AnimalSpec {
  id: string;
  name: string;
  group: "forest" | "water" | "sky" | "desert" | "grassland";
  moveRange: { min: number; max: number };
  hazardResistance: number; // 0-1
  specialAbility: string;
  emoji: string;
  colorPrimary: string;
  colorSecondary: string;
}

export interface QuestionSpec {
  id: string;
  text: string;
  options: string[];
  correctIndex: number;
  zone: "forest" | "ocean" | "desert" | "human_impact" | "restoration";
  explanation: string;
  difficulty: "easy" | "medium" | "hard";
}

